from pathlib import Path
data=json.loads('{"rag/service/plan_chat.py": "", "rag/eval/tests/test_plan_chat.py": ""}')
for n,b in data.items():
 p=Path(n);backup=Path('deploy/backups/chat-location-fix')/n
 if p.exists() and not backup.exists():
  backup.parent.mkdir(parents=True,exist_ok=True);backup.write_bytes(p.read_bytes())
