import json,sqlite3
from pathlib import Path
from unittest.mock import Mock
from retrieval.search_chunks import load_env_files
load_env_files()
from service.plan_chat import advance
p=Path('var/plan_chat.sqlite3')
with sqlite3.connect(p) as db:
 row=db.execute('SELECT state FROM sessions WHERE id=?',('0c38efc5d43145538f3734da77f2b93f',)).fetchone()
assert row,'existing user session missing'
state=json.loads(row[0]);maps=Mock();maps.query.side_effect=AssertionError('No new Baidu query allowed')
def fake_planner(trip):
 assert all('天子驾六博物馆' in d.plan.avoid for d in trip.days)
 return {'status':'time_checked_draft','days':[],'unplanned_days':[]}
new,out=advance(state,'天子驾六博物馆我去过了，换个行不',maps=maps,planner=fake_planner)
assert out['status']=='time_checked_draft',out.get('answer')
assert out['departure_point']['name']=='洛阳站',out.get('departure_point')
maps.query.assert_not_called()
report={'tests_passed':159,'real_extractor_on_existing_session':'passed','planner':'mock_only_no_real_route_calls','new_baidu_calls':0,'session_not_mutated':True,'selected_origin':out['departure_point']['name'],'excluded':'天子驾六博物馆','human_review':None}
Path('rag/eval/reports/chat_location_fix.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(report,ensure_ascii=False))
PY
bash rag/service/stop_retrieval_server.sh
